370	    // 紧接ThreadHandle数组
371	    // 紧接CcuKernelSubmitInfo数组
372	
373	    ThreadHandle* GetThreadHandlePtr() const
374	    {
375	        size_t offset = offsetof(CcuFastLaunchCtx, ccuKernelNum) + sizeof(u32) * MAX_TEMP_NUM_IN_ALGO;
376	        return reinterpret_cast<ThreadHandle*>(reinterpret_cast<char*>(const_cast<CcuFastLaunchCtx*>(this)) + offset);
377	    }
378	    CcuKernelSubmitInfo* GetCcuKernelSubmitInfoPtr() const
379	    {
380	        size_t offset = offsetof(CcuFastLaunchCtx, ccuKernelNum) + sizeof(u32) * MAX_TEMP_NUM_IN_ALGO
381	                        + sizeof(ThreadHandle) * threadNum;
382	        return reinterpret_cast<CcuKernelSubmitInfo*>(
383	            reinterpret_cast<char*>(const_cast<CcuFastLaunchCtx*>(this)) + offset);
384	    }
385	
386	    static u64 GetCtxSize(u32 threadNum, u32 totalCcuKernelNum)
387	    {
388	        return sizeof(CcuFastLaunchCtx) + sizeof(ThreadHandle) * threadNum
389	               + sizeof(CcuKernelSubmitInfo) * totalCcuKernelNum;
390	    }
