455	struct AlgResourceCtxSerializable {
456	    AlgType algType;                              // 环境变量设置的算法类型
457	    AlgHierarchyInfoForAllLevel algHierarchyInfo; // 算法分层信息
458	    HcclMem cclMem;                               // 跨Rank缓存Buffer
459	    u32 notifyNumOnMainThread;                    // 主流上的notify数量
460	    u32 slaveThreadNum;                           // 需要的thread数量
461	    u32 waitTimeout = 0;                          // Device侧notify wait默认超时时间
462	    u32 fullTimeout = 0;                          // Device侧队列满/资源申请超时时间
463	    std::vector<u32> notifyNumPerThread;          // 每个thread需要的notify数量
464	    void* aivCommInfoPtr = nullptr;
465	    std::vector<ThreadHandle> threads;
466	    ThreadHandle unfoldThread = 0; // 展开流thread
467	    std::vector<std::vector<ChannelInfo>> channels;
468	    double dieSplitRatio = 0.0;
469	    bool isHcommBatchTransferOnThreadSupported = false;
470	    bool isHcclThreadAcquireWithConfigSupported = false;
471	    void* commInfoPtr = nullptr;
472	    // hostdpu
473	    void* npu2DpuShmemPtr = nullptr;
474	    void* dpu2NpuShmemPtr = nullptr;
475	    // ccu的
476	    std::vector<u32> ccuKernelNum;
477	    std::vector<CcuKernelHandle> ccuKernels;
478	    u32 topoInfoSeqSize = 0;
479	    TopoInfoWithNetLayerDetails topoInfo; // 提取的拓扑信息
480	
481	    std::vector<char> Serialize()
482	    {
483	        BinaryStream binaryStream;
484	
485	        binaryStream << algType;
486	        binaryStream << algHierarchyInfo.infos;
487	        binaryStream << cclMem;
488	        binaryStream << notifyNumOnMainThread;
489	        binaryStream << slaveThreadNum;
490	        binaryStream << waitTimeout;
491	        binaryStream << fullTimeout;
492	        binaryStream << notifyNumPerThread;
493	        binaryStream << commInfoPtr;
494	        binaryStream << threads;
495	        binaryStream << unfoldThread;
496	        binaryStream << channels;
497	        binaryStream << isHcommBatchTransferOnThreadSupported;
498	        binaryStream << isHcclThreadAcquireWithConfigSupported;
499	
500	        binaryStream << npu2DpuShmemPtr;
501	        binaryStream << dpu2NpuShmemPtr;
502	
503	        binaryStream << ccuKernelNum;
504	        binaryStream << ccuKernels;
505	        binaryStream << dieSplitRatio;
506	        std::vector<char> seq = topoInfo.Serialize();
507	        topoInfoSeqSize = seq.size();
508	        binaryStream << topoInfoSeqSize;
509	        std::vector<char> result;
510	        binaryStream.Dump(result);
511	        result.insert(result.end(), seq.begin(), seq.end());
512	
513	        return result;
514	    }
515	
516	    void DeSerialize(std::vector<char>& data)
517	    {
518	        BinaryStream binaryStream(data);
519	
520	        binaryStream >> algType;
521	        binaryStream >> algHierarchyInfo.infos;
522	        binaryStream >> cclMem;
523	        binaryStream >> notifyNumOnMainThread;
524	        binaryStream >> slaveThreadNum;
525	        binaryStream >> waitTimeout;
526	        binaryStream >> fullTimeout;
527	        binaryStream >> notifyNumPerThread;
528	        binaryStream >> commInfoPtr;
529	        binaryStream >> threads;
530	        binaryStream >> unfoldThread;
531	        binaryStream >> channels;
532	        binaryStream >> isHcommBatchTransferOnThreadSupported;
533	        binaryStream >> isHcclThreadAcquireWithConfigSupported;
534	
535	        binaryStream >> npu2DpuShmemPtr;
536	        binaryStream >> dpu2NpuShmemPtr;
537	
538	        binaryStream >> ccuKernelNum;
539	        binaryStream >> ccuKernels;
540	        binaryStream >> dieSplitRatio;
541	        binaryStream >> topoInfoSeqSize;
542	        size_t startPos = data.size() - topoInfoSeqSize;
543	        std::vector<char> tailData(data.begin() + startPos, data.end());
544	        TopoInfoWithNetLayerDetails topoTemp;
545	        topoTemp.DeSerialize(tailData);
546	        topoInfo = std::move(topoTemp);
547	    }
548	};
