    u32 aicpuRecordCpuIdx = 0;              // aicpu record host的notifyIdx
    u32 dataCount = 0;                      // 算子上报dfx的数据量
    DevAicpuOpConfig opConfig;              // 收编算子配置类变量
    bool aicpuCacheEnable = false;          // aicpu task cache开关
