14	namespace ops_hccl {
15	TopoMatchMultilevel::TopoMatchMultilevel() : TopoMatchBase() {}
16	
17	TopoMatchMultilevel::~TopoMatchMultilevel() {}
18	
19	HcclResult TopoMatchMultilevel::TopoForLayer0(
20	    const HcclComm comm, uint32_t& layer0Size, const uint32_t myRank, AlgHierarchyInfoForAllLevel& algHierarchyInfo,
21	    uint32_t gcdInstSize) const
22	{
23	#ifndef AICPU_COMPILE
24	    uint32_t* topoInsts;
25	    uint32_t topoInstNum = 0;
26	    CHK_RET(HcclRankGraphGetTopoInstsByLayer(comm, 0, &topoInsts, &topoInstNum));
27	
28	    if (topoInstNum == NET_INST_NUM_1) {
29	        // mesh1d
30	        HCCL_INFO("[CollAlgFactory] [TopoMatchMultilevel] layer0 topoInstNum [%d], Mesh 1D.", topoInstNum);
31	        uint32_t* ranks;
32	        uint32_t rankNum = 0;
33	        CHK_RET(HcclRankGraphGetRanksByTopoInst(comm, 0, topoInsts[0], &ranks, &rankNum));
34	        HCCL_DEBUG(
35	            "[CollAlgFactory] [TopoMatchMultilevel] Rank [%d], all [%u] ranks in this pod: [%s]", myRank, rankNum,
36	            PrintCArray<uint32_t>(ranks, rankNum).c_str());
37	        if (gcdInstSize > 0 && gcdInstSize < rankNum) {
38	            // Asymmetric: split this pod into GCD-sized subgroups
39	            // ranks guaranteed ascending by HcclRankGraphGetRanksByTopoInst (backed by std::set)
40	            auto it = std::find(ranks, ranks + rankNum, myRank);
41	            CHK_PRT_RET(
42	                it == ranks + rankNum,
43	                HCCL_ERROR("[TopoMatchMultilevel] [TopoForLayer0] myRank [%u] not found in ranks array", myRank),
44	                HcclResult::HCCL_E_INTERNAL);
45	
46	            uint32_t myIdx = static_cast<uint32_t>(it - ranks);
47	            uint32_t groupId = myIdx / gcdInstSize;
48	            uint32_t startIdx = groupId * gcdInstSize;
49	            uint32_t endIdx = std::min(startIdx + gcdInstSize, rankNum);
50	            std::vector<uint32_t> rankVecLayer0(ranks + startIdx, ranks + endIdx);
51	            HCCL_DEBUG(
52	                "[TopoMatchMultilevel] [TopoForLayer0] Rank [%d], GCD subgroup: [%s]", myRank,
53	                PrintCArray<uint32_t>(rankVecLayer0.data(), static_cast<u32>(rankVecLayer0.size())).c_str());
54	            algHierarchyInfo.infos[0].push_back({rankVecLayer0});
55	            layer0Size = gcdInstSize;
56	        } else {
57	            // Symmetric: original logic (whole pod as one group)
58	            std::vector<uint32_t> rankVecLayer0(ranks, ranks + rankNum);
59	            algHierarchyInfo.infos[0].push_back({rankVecLayer0});
60	            layer0Size = rankVecLayer0.size();
61	        }
62	    } else if (topoInstNum == 0) {
63	        algHierarchyInfo.infos[0].push_back({{myRank}});
64	        layer0Size = 1;
65	    } else if (topoInstNum >= NET_INST_NUM_2) {
66	        // mesh2d
67	        HCCL_INFO("[CollAlgFactory] [TopoMatchMultilevel] layer0 topoInstNum [%d], Mesh 1D.", topoInstNum);
68	        std::vector<uint32_t> ranks_x;
69	        std::vector<uint32_t> ranks_y;
70	
71	        for (uint32_t idx = 0; idx < topoInstNum; idx++) {
72	            CommTopo topoType;
73	            CHK_RET(HcclRankGraphGetTopoType(comm, 0, topoInsts[idx], &topoType));
74	            if (topoType == CommTopo::COMM_TOPO_CLOS)
75	                continue;
76	
77	            uint32_t* ranks;
78	            uint32_t rankNum;
79	            CHK_RET(HcclRankGraphGetRanksByTopoInst(comm, 0, topoInsts[idx], &ranks, &rankNum));
80	
81	            std::sort(ranks, ranks + rankNum);
82	            if (rankNum >= 2 && ranks[1] - ranks[0] == 1) {
83	                ranks_x.assign(ranks, ranks + rankNum);
84	            } else {
85	                ranks_y.assign(ranks, ranks + rankNum);
86	            }
87	        }
88	        if (ranks_x.size() != 0) {
89	            algHierarchyInfo.infos[0].push_back(ranks_x);
90	            layer0Size = ranks_x.size();
91	        }
92	        if (ranks_y.size() != 0) {
93	            algHierarchyInfo.infos[0].push_back(ranks_y);
94	            if (layer0Size == 0) {
95	                layer0Size = ranks_y.size();
96	            } else {
97	                layer0Size *= ranks_y.size();
98	            }
99	        }
100	    }
101	#endif
102	    return HcclResult::HCCL_SUCCESS;
103	}
104	
105	HcclResult TopoMatchMultilevel::TopoForLayer1(
106	    const HcclComm comm, uint32_t netLayer, uint32_t& layer0Size, const uint32_t myRank,
107	    AlgHierarchyInfoForAllLevel& algHierarchyInfo) const
108	{
109	    HCCL_DEBUG("[TopoMatchMultilevel::MeshNHRTopoForLayer1] layer0Size [%d]", layer0Size);
110	#ifndef AICPU_COMPILE
111	    // 1. 查出layer 1的所有ranks
112	    uint32_t* topoInsts;
113	    uint32_t topoInstNum = 0;
114	    CHK_RET(HcclRankGraphGetTopoInstsByLayer(comm, netLayer, &topoInsts, &topoInstNum));
115	    CHK_PRT_RET(
116	        (topoInstNum != NET_INST_NUM_1),
117	        HCCL_ERROR("[TopoMatchMultilevel::MeshNHRTopoForLayer1] layer1 topoInstNum [%d], Invalid topo.", topoInstNum),
118	        HcclResult::HCCL_E_PARA);
119	
120	    uint32_t* ranks;
121	    uint32_t rankNum;
122	    CHK_RET(HcclRankGraphGetRanksByTopoInst(comm, netLayer, topoInsts[0], &ranks, &rankNum));
123	    HCCL_DEBUG("[TopoMatchMultilevel::MeshNHRTopoForLayer1] Rank [%d], all [%u] ranks in layer1", myRank, rankNum);
124	
125	    // 2. 取出同序号卡，作为layer1的ranks
126	    std::vector<uint32_t> rankVecLayer1WithSameIdx;
127	    for (uint32_t i = 0; i < rankNum; i++) {
128	        uint32_t rankId = ranks[i];
129	        if (myRank == rankId) {
130	            rankVecLayer1WithSameIdx.push_back(rankId);
131	            continue;
132	        }
133	        if (layer0Size == 0) {
134	            HCCL_ERROR("[TopoMatchMultilevel::MeshNHRTopoForLayer1] layer0Size is 0, Invalid topo.");
135	            return HcclResult::HCCL_E_PARA;
136	        }
137	        if (rankId % layer0Size != myRank % layer0Size) {
138	            continue;
139	        }
140	        CommLink* links;
141	        uint32_t linkNum = 0;
142	        CHK_RET(HcclRankGraphGetLinks(comm, netLayer, myRank, rankId, &links, &linkNum));
143	        if (linkNum == 0) {
144	            continue;
145	        }
146	        rankVecLayer1WithSameIdx.push_back(rankId);
147	    }
148	    algHierarchyInfo.infos[1].push_back({rankVecLayer1WithSameIdx});
149	#endif
150	    return HcclResult::HCCL_SUCCESS;
151	}
152	
153	bool TopoMatchMultilevel::CheckVecElementAllSame(const uint32_t* instSizeList, uint32_t listSize) const
154	{
155	#ifndef AICPU_COMPILE
156	    uint32_t firstSize = instSizeList[0];
157	    for (uint32_t i = 1; i < listSize; i++) {
158	        if (firstSize != instSizeList[i]) {
159	            return false;
160	        }
161	    }
162	#endif
163	    return true;
164	}
165	
166	uint32_t TopoMatchMultilevel::GcdTwo(uint32_t a, uint32_t b) const
167	{
168	    while (b != 0) {
169	        a %= b;
170	        std::swap(a, b);
171	    }
172	    return a;
173	}
174	
175	uint32_t TopoMatchMultilevel::GcdOfInstSizeList(const uint32_t* instSizeList, uint32_t listSize) const
176	{
177	    uint32_t result = instSizeList[0];
178	    for (uint32_t i = 1; i < listSize; i++) {
179	        result = GcdTwo(result, instSizeList[i]);
180	        if (result == 1) {
181	            return 1;
182	        }
183	    }
184	    return result;
185	}
186	
187	HcclResult TopoMatchMultilevel::TopoForLayer2(
188	    const HcclComm comm, uint32_t netLayer, uint32_t layer0Size, uint32_t layer1Size, const uint32_t myRank,
189	    AlgHierarchyInfoForAllLevel& algHierarchyInfo) const
190	{
191	    HCCL_DEBUG("[TopoMatchMultilevel::TopoForLayer2] layer0Size [%u] layer1Size [%u]", layer0Size, layer1Size);
192	#ifndef AICPU_COMPILE
193	    uint32_t* topoInsts;
194	    uint32_t topoInstNum = 0;
195	    CHK_RET(HcclRankGraphGetTopoInstsByLayer(comm, netLayer, &topoInsts, &topoInstNum));
196	    CHK_PRT_RET(
197	        (topoInstNum != NET_INST_NUM_1),
198	        HCCL_ERROR("[TopoMatchMultilevel::TopoForLayer2] layer2 topoInstNum [%d], Invalid topo.", topoInstNum),
199	        HcclResult::HCCL_E_PARA);
200	
201	    uint32_t* ranks;
202	    uint32_t rankNum;
203	    CHK_RET(HcclRankGraphGetRanksByTopoInst(comm, netLayer, topoInsts[0], &ranks, &rankNum));
204	    HCCL_DEBUG("[TopoMatchMultilevel::TopoForLayer2] Rank [%d], all [%u] ranks in layer2", myRank, rankNum);
205	
206	    std::vector<uint32_t> rankVecLayer2WithSameIdx;
207	    for (uint32_t i = 0; i < rankNum; i++) {
208	        uint32_t rankId = ranks[i];
209	        if (myRank == rankId) {
210	            rankVecLayer2WithSameIdx.push_back(rankId);
211	            continue;
212	        }
213	        if (layer0Size == 0 || layer1Size == 0) {
214	            HCCL_ERROR("[TopoMatchMultilevel::TopoForLayer2] layer0Size or layer1Size is 0, Invalid topo.");
215	            return HcclResult::HCCL_E_PARA;
216	        }
217	        if (rankId % (layer0Size * layer1Size) != myRank % (layer0Size * layer1Size)) {
218	            continue;
219	        }
220	        CommLink* links;
221	        uint32_t linkNum = 0;
222	        CHK_RET(HcclRankGraphGetLinks(comm, netLayer, myRank, rankId, &links, &linkNum));
223	        if (linkNum == 0) {
224	            continue;
225	        }
226	        rankVecLayer2WithSameIdx.push_back(rankId);
227	    }
228	    algHierarchyInfo.infos[2].push_back({rankVecLayer2WithSameIdx});
229	#endif
230	    return HcclResult::HCCL_SUCCESS;
231	}
232	
233	HcclResult TopoMatchMultilevel::MatchTopo(
234	    const HcclComm comm, TopoInfoWithNetLayerDetails* topoInfo, AlgHierarchyInfoForAllLevel& algHierarchyInfo)
235	{
236	#ifndef AICPU_COMPILE
237	    CHK_PRT_RET(
238	        topoInfo->topoLevelNums == 0 || topoInfo->topoLevelNums > COMM_LAYER_SIZE_3,
239	        HCCL_ERROR("[CalcTopoLevelNums] topoLevelNum[%u] is invalid.", topoInfo->topoLevelNums), HCCL_E_INTERNAL);
240	
241	    uint32_t myRank;
242	    CHK_RET(HcclGetRankId(comm, &myRank));
243	    CHK_PRT_RET(
244	        !shouldGoOutPlace(topoInfo->deviceType),
245	        HCCL_ERROR("[CollAlgFactory] [TopoMatchMultilevel] Rank [%d], deviceType not supported yet.", myRank),
246	        HcclResult::HCCL_E_PARA);
247	    // 1.获取并校验通信层数
248	    uint32_t* netLayersTemp = nullptr;
249	    uint32_t layerNum = 0;
250	    CHK_RET(HcclRankGraphGetLayers(comm, &netLayersTemp, &layerNum));
251	    CHK_PRT_RET(
252	        netLayersTemp == nullptr || layerNum == 0,
253	        HCCL_ERROR("[TopoMatchMultilevel][MatchTopo] Rank [%u], invalid net layers, layerNum[%u].", myRank, layerNum),
254	        HcclResult::HCCL_E_INTERNAL);
255	    std::vector<uint32_t> netLayerList(netLayersTemp, netLayersTemp + layerNum);
256	
257	    HCCL_DEBUG(
258	        "[CollAlgFactory] [TopoMatchMultilevel] Rank [%d], netLayers[%u][%s]", myRank, layerNum,
259	        PrintCArray<uint32_t>(netLayerList.data(), layerNum).c_str());
260	
261	    // 2. 获取每个pod上rank数量以及pod数量
262	    uint32_t* instSizeList;
263	    uint32_t listSize = 0;
264	    CHK_RET(HcclRankGraphGetInstSizeListByLayer(comm, 0, &instSizeList, &listSize));
265	    HCCL_INFO(
266	        "[CollAlgFactory] [TopoMatchMultilevel] Rank [%d], [%u] pods ,ranksize on each pod :[%s]", myRank, listSize,
267	        PrintCArray<uint32_t>(instSizeList, listSize).c_str());
268	    bool isSymmetric = CheckVecElementAllSame(instSizeList, listSize);
269	    HCCL_INFO(
270	        "[TopoMatchMultilevel][MatchTopo] Rank [%d], isSymmetric[%d], topoLevelNums[%u], listSize[%u]", myRank,
271	        isSymmetric, topoInfo->topoLevelNums, listSize);
272	
273	    // 检查物理layer1（pod间）对称性：每个pod内的instance数是否相同
274	    bool layer1Symmetric = true;
275	    uint32_t physicalLayer1NetLayer = 1;
276	    uint32_t algLayer1NetLayer = 1;
277	    if (topoInfo->topoLevelNums > 1) {
278	        CHK_PRT_RET(
279	            layerNum < COMM_LAYER_SIZE_2,
280	            HCCL_ERROR(
281	                "[TopoMatchMultilevel][MatchTopo] Rank [%u], net layer num[%u] is invalid for "
282	                "topoLevelNums[%u].",
283	                myRank, layerNum, topoInfo->topoLevelNums),
284	            HcclResult::HCCL_E_INTERNAL);
285	        physicalLayer1NetLayer = netLayerList[1];
286	        algLayer1NetLayer = physicalLayer1NetLayer;
287	    }
288	
289	    bool hostDPUOnly = false;
290	    if ((CheckHostDPUOnly(comm, topoInfo, hostDPUOnly) == HcclResult::HCCL_SUCCESS) && hostDPUOnly) {
291	        // host dpu场景使用最高层的链路
292	        algLayer1NetLayer = netLayerList.back();
293	    }
294	    if (topoInfo->topoLevelNums > 1) {
295	        uint32_t* layer1InstSizeList = nullptr;
296	        uint32_t layer1ListSize = 0;
297	        CHK_RET(
298	            HcclRankGraphGetInstSizeListByLayer(comm, physicalLayer1NetLayer, &layer1InstSizeList, &layer1ListSize));
299	        HCCL_INFO("[TopoMatchMultilevel][MatchTopo] layer1 listSize[%u]", layer1ListSize);
300	        for (uint32_t i = 0; i < layer1ListSize; i++) {
301	            HCCL_INFO("[TopoMatchMultilevel][MatchTopo] layer1 instSizeList[%u]=[%u]", i, layer1InstSizeList[i]);
302	        }
303	        layer1Symmetric = CheckVecElementAllSame(layer1InstSizeList, layer1ListSize);
304	        HCCL_INFO("[TopoMatchMultilevel][MatchTopo] layer1Symmetric[%d]", layer1Symmetric);
305	    }
306	
307	    // 三级拓扑暂不支持任何非对称场景（layer0 或 layer1）
308	    if (topoInfo->topoLevelNums >= COMM_LAYER_SIZE_3 && (!isSymmetric || !layer1Symmetric)) {
309	        HCCL_ERROR(
310	            "[TopoMatchMultilevel][MatchTopo] Asymmetric mode not supported for 3-level topology, "
311	            "topoLevelNums[%u], isSymmetric[%d], layer1Symmetric[%d]",
312	            topoInfo->topoLevelNums, isSymmetric, layer1Symmetric);
313	        return HcclResult::HCCL_E_NOT_SUPPORT;
314	    }
315	
316	    // 非对称仅支持 Mesh1D，提前校验 topoInstNum
317	    if (!isSymmetric) {
318	        HCCL_INFO(
319	            "[TopoMatchMultilevel][MatchTopo] Asymmetric mode detected, "
320	            "topoLevelNums[%u], listSize[%u]",
321	            topoInfo->topoLevelNums, listSize);
322	        for (uint32_t i = 0; i < listSize; i++) {
323	            HCCL_INFO("[TopoMatchMultilevel][MatchTopo] Asymmetric instSizeList[%u]=[%u]", i, instSizeList[i]);
324	        }
325	
326	        uint32_t* topoInsts;
327	        uint32_t topoInstNum = 0;
328	        CHK_RET(HcclRankGraphGetTopoInstsByLayer(comm, 0, &topoInsts, &topoInstNum));
329	        HCCL_INFO("[TopoMatchMultilevel][MatchTopo] Asymmetric mode, topoInstNum[%u]", topoInstNum);
330	        CHK_PRT_RET(
331	            topoInstNum != NET_INST_NUM_1,
332	            HCCL_ERROR(
333	                "[TopoMatchMultilevel][MatchTopo] Asymmetric mode only supports Mesh1D, "
334	                "but topoInstNum [%u]",
335	                topoInstNum),
336	            HcclResult::HCCL_E_NOT_SUPPORT);
337	    }
338	
339	    // 3. 计算layer0的topo
340	    bool needDowngrade = hostDPUOnly && topoInfo->topoLevelNums == COMM_LAYER_SIZE_3;
341	    uint32_t commLayerSize
342	        = (topoInfo->topoLevelNums == COMM_LAYER_SIZE_3 && !needDowngrade) ? COMM_LAYER_SIZE_3 : COMM_LAYER_SIZE_2;
343	    algHierarchyInfo.infos.resize(commLayerSize);
344	    if (needDowngrade) {
345	        HCCL_INFO(
346	            "[TopoMatchMultilevel][MatchTopo] Rank [%u], downgrade HostDPU topology from physical "
347	            "level nums[%u] to algorithm level nums[%u], algorithm layer1 uses net layer[%u].",
348	            myRank, topoInfo->topoLevelNums, commLayerSize, algLayer1NetLayer);
349	    }
350	    uint32_t layer0Size = 0;
351	    if (!isSymmetric) {
352	        uint32_t gcdInstSize = GcdOfInstSizeList(instSizeList, listSize);
353	        HCCL_INFO("[TopoMatchMultilevel][MatchTopo] Asymmetric mode, gcdInstSize [%u]", gcdInstSize);
354	        CHK_RET(TopoForLayer0(comm, layer0Size, myRank, algHierarchyInfo, gcdInstSize));
355	    } else {
356	        CHK_RET(TopoForLayer0(comm, layer0Size, myRank, algHierarchyInfo));
357	    }
358	
359	    // 4. 计算layer1的topo
360	    CHK_RET(TopoForLayer1(comm, algLayer1NetLayer, layer0Size, myRank, algHierarchyInfo));
361	
362	    // 5. 计算layer2的topo (3层拓扑场景)
363	    if (topoInfo->topoLevelNums >= COMM_LAYER_SIZE_3 && !needDowngrade) {
364	        uint32_t layer1Size = algHierarchyInfo.infos[1][0].size();
365	        uint32_t netLayer2 = topoInfo->netLayerDetails.netLayers[topoInfo->netLayerDetails.netLayerNum - 1];
366	        CHK_RET(TopoForLayer2(comm, netLayer2, layer0Size, layer1Size, myRank, algHierarchyInfo));
367	    }
368	#endif
369	    return HcclResult::HCCL_SUCCESS;
370	}
371	
372	} // namespace ops_hccl
