84	Selector(HcclComm comm, OpParam& param, std::unique_ptr<TopoInfoWithNetLayerDetails>& topoInfo, std::string& algName)
85	{
86	    // 判断通信域状态
87	    HcclCommStatus commStatus = HCCL_COMM_STATUS_INVALID;
88	    if (HcommIsSupportHcclCommGetStatus()) {
89	        CHK_RET(HcclCommGetStatus(param.commName, &commStatus));
90	        if (commStatus != HCCL_COMM_STATUS_READY) {
91	            HCCL_ERROR("commStatus is not ready!, commStatus = %d", static_cast<int>(commStatus));
92	            return HCCL_E_SUSPENDING;
93	        }
94	    }
95	    HCCL_INFO("Start to execute Selector.");
96	    param.hcclComm = comm;
97	    // 获取基础拓扑
98	    CHK_RET(HcclCalcTopoInfo(comm, param, topoInfo));
99	
100	    // 算法选择，选择完后顺便param.algTag设置了，资源的保存是以算子+算法为单位
101	    std::shared_ptr<ExecuteSelector> collAlgSelector = std::make_shared<ExecuteSelector>(ExecuteSelector());
102	    CHK_RET(collAlgSelector->Run(param, topoInfo.get(), algName));
103	    if (algName == "") {
104	        HCCL_ERROR("[Selector] select algname fail!");
105	        return HCCL_E_PTR;
106	    }
107	    CHK_RET(SetCommEngine(param));
108	    // AIV_ONLY 模式下禁止回退到非 AIV 引擎，未选中 AIV 时直接返回不支持。
109	    if (param.commOpExpansionMode == HcclOpExpansionMode::HCCL_OP_EXPANSION_AIV_ONLY
110	        && param.engine != CommEngine::COMM_ENGINE_AIV) {
111	        HCCL_ERROR(
112	            "[HcclExecOp] opType[%d] currently do not select aiv mode, aiv only not support.",
113	            static_cast<int>(param.opType));
114	        return HCCL_E_NOT_SUPPORT;
115	    }
116	    // 如果一开始读取到的Engine不是aicpu，经过算法选择后回退到aicpu，则需要重新LoadAICPUKernel
117	    if ((param.engine == CommEngine::COMM_ENGINE_AICPU_TS) || (param.engine == CommEngine::COMM_ENGINE_CPU)) {
118	        HCCL_DEBUG("[Selector] is aicpu mode");
119	        CHK_RET(LoadAICPUKernel()); // 该函数内部有防止重复加载的逻辑
120	        // 在三级组网下走clos链路时，aicpu引擎目前仅支持NHR算法
121	        HCCL_WARNING("under 3-level topology with CLOS link, aicpu engine currently only supports NHR algorithm.");
122	    }
123	    // 如果一开始读取到的Engine不是aiv，经过算法选择后回退到aiv，则需要重新RegisterKernel
124	    if (param.engine == CommEngine::COMM_ENGINE_AIV) {
125	        HCCL_DEBUG("[Selector] is aiv mode");
126	        CHK_RET(RegisterKernel()); // 该函数内部有防止重复加载的逻辑
127	    }
128	    CHK_RET(SetOpParamAlgTag(param, algName));
129	    // 设定执行超时时间
130	    CHK_RET(SetExecTimeout(param));
131	    // 获取多维度切分比例
132	    CHK_RET(SetMultipleDimensionSplitRatio(comm, param));
133	    HCCL_INFO("Success to execute Selector.");
134	    return HCCL_SUCCESS;
